package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.NotificationManager;import android.content.*;import android.media.AudioManager;
/** Shared, explicitly selected profiles. No scheduled or automatic changes. */
final class SoundProfiles {
    static final String[] NAMES=L.array(new String[]{"Normal","Silențios","Exterior","Noapte · alarma rămâne","Profilul meu","Salvează nivelurile curente"});
    private static final int[] STREAMS={AudioManager.STREAM_MUSIC,AudioManager.STREAM_RING,AudioManager.STREAM_ALARM};
    static String current(Context c){if(SoundSchedule.prefs(c).getBoolean("active",false))return SoundSchedule.prefs(c).getBoolean("night",true)?L.t("Noapte programată"):L.t("Silențios programat");AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);return a.getRingerMode()==AudioManager.RINGER_MODE_SILENT?(((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getCurrentInterruptionFilter()==NotificationManager.INTERRUPTION_FILTER_ALARMS?L.t("Noapte · alarma rămâne"):L.t("Silențios")):a.getRingerMode()==AudioManager.RINGER_MODE_VIBRATE?L.t("Vibrații"):c.getSharedPreferences("sound-profile",0).getString("label","Normal");}
    static void select(final LeoActivity c,final Runnable changed){c.options(L.t("Profil sonor"),NAMES,new LeoActivity.Choice(){public void pick(int i){try{apply(c,i);if(i==5)c.notice(L.t("Nivelurile personale au fost salvate"));changed.run();}catch(RuntimeException failure){c.notice(failure.getMessage()==null?L.t("Profil nesalvat"):failure.getMessage());}}});}
    static void apply(Context c,int which){AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);SharedPreferences p=c.getSharedPreferences("sound-profile",0);
        if(which==5){SharedPreferences.Editor edit=p.edit().putBoolean("saved",true).putInt("filter",((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getCurrentInterruptionFilter()).putInt("mode",a.getRingerMode());for(int i=0;i<STREAMS.length;i++)edit.putInt("volume"+i,a.getStreamVolume(STREAMS[i]));edit.apply();return;}
        if(!((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).isNotificationPolicyAccessGranted())throw new IllegalStateException(L.t("Acces Nu deranjați neacordat"));
        SoundSchedule.manual(c);
        if(which==4){if(!p.getBoolean("saved",false))throw new IllegalStateException(L.t("Salvează întâi nivelurile curente"));for(int i=0;i<STREAMS.length;i++)a.setStreamVolume(STREAMS[i],Math.min(a.getStreamMaxVolume(STREAMS[i]),p.getInt("volume"+i,0)),0);a.setRingerMode(p.getInt("mode",AudioManager.RINGER_MODE_NORMAL));((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).setInterruptionFilter(p.getInt("filter",NotificationManager.INTERRUPTION_FILTER_ALL));}
        else if(which==1||which==3){if(which==1)((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_ALL);if(which==3){if(!p.contains("night_music"))p.edit().putInt("night_music",a.getStreamVolume(AudioManager.STREAM_MUSIC)).apply();a.setStreamVolume(AudioManager.STREAM_MUSIC,0,0);if(FmService.instance!=null){if(!p.contains("night_fm"))p.edit().putInt("night_fm",FmService.volume).apply();FmService.instance.setVolume(0);}}a.setRingerMode(AudioManager.RINGER_MODE_SILENT);if(which==3)((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_ALARMS);}
        else {((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_ALL);a.setRingerMode(AudioManager.RINGER_MODE_NORMAL);int max=a.getStreamMaxVolume(AudioManager.STREAM_RING);if(which==2||a.getStreamVolume(AudioManager.STREAM_RING)==0)a.setStreamVolume(AudioManager.STREAM_RING,which==2?max:Math.max(1,max/2),0);}
        if(which!=3&&p.contains("night_music")){if(which!=4&&a.getStreamVolume(AudioManager.STREAM_MUSIC)==0)a.setStreamVolume(AudioManager.STREAM_MUSIC,Math.min(a.getStreamMaxVolume(AudioManager.STREAM_MUSIC),p.getInt("night_music",0)),0);p.edit().remove("night_music").apply();}if(which!=3&&p.contains("night_fm")){if(FmService.instance!=null&&FmService.volume==0)FmService.instance.setVolume(p.getInt("night_fm",8));p.edit().remove("night_fm").apply();}p.edit().putString("label",NAMES[which]).apply();
    }
}
